  // src/state/site-enable.js
  function isMasterThemingEnabled() {
    return store.getState()?.global?.enabled !== false;
  }
  async function toggleSiteTheming() {
    await store.ready;
    const next = !isMasterThemingEnabled();
    await store.update({ enabled: next });
    return next;
  }

